CREATE TABLE food_sources (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, edition TEXT NOT NULL,
  reference TEXT NOT NULL DEFAULT '', imported_at TEXT NOT NULL
);
CREATE TABLE foods (
  id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES food_sources(id),
  source_item_id TEXT, name TEXT NOT NULL CHECK(length(trim(name))>0),
  category TEXT NOT NULL DEFAULT '',
  base_amount REAL NOT NULL DEFAULT 100 CHECK(base_amount>0),
  base_unit TEXT NOT NULL DEFAULT 'g' CHECK(base_unit IN('g','ml','unidade','colher','xícara','porção')),
  edible_portion REAL NOT NULL DEFAULT 1 CHECK(edible_portion>0 AND edible_portion<=1),
  is_custom INTEGER NOT NULL DEFAULT 0 CHECK(is_custom IN(0,1)),
  custom_nutrients_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(custom_nutrients_json)),
  notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
  archived_at TEXT, UNIQUE(source_id,source_item_id)
);
CREATE INDEX foods_search ON foods(archived_at,source_id,name);
CREATE TABLE food_nutrients (
  food_id TEXT NOT NULL REFERENCES foods(id) ON DELETE CASCADE,
  nutrient_key TEXT NOT NULL, amount REAL CHECK(amount>=0), unit TEXT NOT NULL,
  qualifier TEXT NOT NULL DEFAULT 'measured' CHECK(qualifier IN('measured','trace')),
  PRIMARY KEY(food_id,nutrient_key),
  CHECK((qualifier='trace' AND amount IS NULL) OR (qualifier='measured' AND amount IS NOT NULL))
);
CREATE INDEX food_nutrients_key ON food_nutrients(nutrient_key,food_id);
CREATE TRIGGER custom_food_nutrients_insert AFTER INSERT ON foods WHEN NEW.is_custom=1
BEGIN
  INSERT INTO food_nutrients(food_id,nutrient_key,amount,unit)
  SELECT NEW.id,j.key,j.value,
   CASE WHEN j.key LIKE '%_kcal' THEN 'kcal' WHEN j.key LIKE '%_mcg%' THEN 'mcg' WHEN j.key LIKE '%_mg' THEN 'mg' ELSE 'g' END
  FROM json_each(NEW.custom_nutrients_json) j;
END;
CREATE TRIGGER custom_food_nutrients_update AFTER UPDATE OF custom_nutrients_json ON foods WHEN NEW.is_custom=1
BEGIN
  DELETE FROM food_nutrients WHERE food_id=NEW.id;
  INSERT INTO food_nutrients(food_id,nutrient_key,amount,unit)
  SELECT NEW.id,j.key,j.value,
   CASE WHEN j.key LIKE '%_kcal' THEN 'kcal' WHEN j.key LIKE '%_mcg%' THEN 'mcg' WHEN j.key LIKE '%_mg' THEN 'mg' ELSE 'g' END
  FROM json_each(NEW.custom_nutrients_json) j;
END;
CREATE TABLE meals (
  id TEXT PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name))>0),
  notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,
  archived_at TEXT
);
CREATE TABLE meal_items (
  id TEXT PRIMARY KEY,meal_id TEXT NOT NULL REFERENCES meals(id) ON DELETE CASCADE,
  food_id TEXT NOT NULL REFERENCES foods(id),quantity REAL NOT NULL CHECK(quantity>0),
  unit TEXT NOT NULL CHECK(unit IN('g','ml','unidade','colher','xícara','porção')),
  grams_equivalent REAL NOT NULL CHECK(grams_equivalent>0),
  notes TEXT NOT NULL DEFAULT '',sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
CREATE INDEX meal_items_order ON meal_items(meal_id,sort_order);
CREATE TABLE diet_plans (
  id TEXT PRIMARY KEY,name TEXT NOT NULL CHECK(length(trim(name))>0),
  description TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 0 CHECK(active IN(0,1)),
  created_at TEXT NOT NULL,updated_at TEXT NOT NULL,archived_at TEXT
);
CREATE UNIQUE INDEX diet_active_plan ON diet_plans(active) WHERE active=1;
CREATE TRIGGER diet_activate BEFORE UPDATE OF active ON diet_plans WHEN NEW.active=1
BEGIN UPDATE diet_plans SET active=0 WHERE id<>NEW.id AND active=1; END;
CREATE TABLE diet_meals (
  id TEXT PRIMARY KEY,diet_plan_id TEXT NOT NULL REFERENCES diet_plans(id) ON DELETE CASCADE,
  weekday INTEGER NOT NULL CHECK(weekday BETWEEN 0 AND 6),
  meal_id TEXT NOT NULL REFERENCES meals(id),sort_order INTEGER NOT NULL DEFAULT 0,
  UNIQUE(diet_plan_id,weekday,meal_id)
);
CREATE INDEX diet_meals_day ON diet_meals(diet_plan_id,weekday,sort_order);
CREATE TABLE food_diary_entries (
  id TEXT PRIMARY KEY,entry_date TEXT NOT NULL CHECK(entry_date GLOB '????-??-??'),
  meal_label TEXT NOT NULL DEFAULT 'Outros',food_id TEXT NOT NULL REFERENCES foods(id),
  food_name TEXT NOT NULL,quantity REAL NOT NULL CHECK(quantity>0),
  unit TEXT NOT NULL CHECK(unit IN('g','ml','unidade','colher','xícara','porção')),
  grams_equivalent REAL NOT NULL CHECK(grams_equivalent>0),
  nutrients_json TEXT NOT NULL CHECK(json_valid(nutrients_json)),
  source_meal_id TEXT REFERENCES meals(id) ON DELETE SET NULL,
  notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
CREATE INDEX food_diary_date ON food_diary_entries(entry_date,meal_label);
CREATE TABLE nutrition_goals (
  id INTEGER PRIMARY KEY CHECK(id=1),calories REAL CHECK(calories>0),
  carbs_g REAL CHECK(carbs_g>0),protein_g REAL CHECK(protein_g>0),
  fat_g REAL CHECK(fat_g>0),updated_at TEXT NOT NULL
);
CREATE TABLE body_weight_entries (
  id TEXT PRIMARY KEY,entry_date TEXT NOT NULL CHECK(entry_date GLOB '????-??-??'),
  weight_kg REAL NOT NULL CHECK(weight_kg>0 AND weight_kg<1000),
  notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL
);
CREATE INDEX body_weight_date ON body_weight_entries(entry_date DESC);
